/*
 * components/illustrations/index.js
 * Barrel export — import any illustration from one path.
 */
export { default as ChatIllus     } from './ChatIllus';
export { default as ChatSideIllus } from './ChatSideIllus';
export { default as ReelIcon      } from './ReelIcon';
